def sol(s): return '// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\ncontract Lesson {\n'+s+'\n}\n'
def pl(decl,body): return 'SET SERVEROUTPUT ON\nDECLARE\n'+decl+'\nBEGIN\n'+body+'\nEND;\n/\n'
course('solidity','Solidity','solidity','Examples use Solidity 0.8.24 or a compatible 0.8.x compiler.','Paste one contract into Remix and choose compiler 0.8.24 or later in the 0.8 series. Deploy only to Remix VM for practice. Call the function named in the lesson; shown results are return values.','Solidity describes smart contracts. A smart contract is code stored and run by a blockchain system.',[
L('first-result','Return a greeting','A contract groups functions and data. Call message() to read a greeting without changing stored data.',sol('function message() external pure returns (string memory) { return "Hello, Asha!"; }'),'Hello, Asha!','Change the greeting and redeploy in Remix VM.','Use the practice VM; no wallet or real money is needed.'),
L('numbers','Return a whole number','uint256 stores a nonnegative whole number. Call answer() to add two small counts.',sol('function answer() external pure returns (uint256) { return 3 + 2; }'),'5','Add 6 and 4.','Unsigned numbers cannot represent negative values.'),
L('state','Read stored state','A state variable lives in contract storage. public creates a getter. Call score().',sol('uint256 public score = 3;'),'3','Change the initial value before a new VM deployment.','Changing source code does not change a contract already deployed.'),
L('parameters','Use a function input','A parameter is an input value. Call twice(4) in Remix.',sol('function twice(uint256 n) external pure returns (uint256) { return n * 2; }'),'8','Call twice(7).','Very large products can overflow and revert in Solidity 0.8.'),
L('choices','Choose a message','if selects a result based on a rule. Call message(8).',sol('function message(uint256 score) external pure returns (string memory) { if (score >= 5) return "Pass"; return "Try again"; }'),'Pass','Call message(3).','Specify memory for this returned string.'),
L('arrays','Read an array item','A memory array is temporary data for the call. Call answer() to read its second item.',sol('function answer() external pure returns (uint256) { uint256[] memory scores = new uint256[](2); scores[0] = 4; scores[1] = 8; return scores[1]; }'),'8','Read scores[0] instead.','An index outside the array reverts the call.'),
L('loops','Add values in a loop','A for loop repeats steps. Call answer() to add 1, 2 and 3.',sol('function answer() external pure returns (uint256) { uint256 total; for (uint256 n = 1; n <= 3; n++) { total += n; } return total; }'),'6','Add through 4 instead.','Unbounded loops can use too much gas in real transactions.'),
L('enums','Name a fixed choice','An enum names a small set of choices. Call answer() to read the chosen case number.',sol('enum Light { Red, Green }\nfunction answer() external pure returns (uint256) { return uint256(Light.Green); }'),'1','Return Light.Red.','Enum case numbers start at zero.'),
L('structs','Group fields','A struct groups related fields. Call answer() to read a book page count.',sol('struct Book { string title; uint256 pages; }\nfunction answer() external pure returns (uint256) { Book memory book = Book("Moon Trip", 24); return book.pages; }'),'24','Change the page count.','Choose memory for a temporary struct used only inside a call.'),
L('mappings','Read a mapping value','A mapping pairs keys with values. Unset integer keys return zero. Call scoreOf(1).',sol('mapping(uint256 => uint256) public scoreOf;'),'0','Call another unused key.','A zero result does not tell you whether a key was ever written.'),
L('validation','Reject an invalid input','require stops a call when its rule is false. Call check(0) to see the error.',sol('function check(uint256 amount) external pure returns (uint256) { require(amount > 0, "Use a positive amount"); return amount; }'),'revert: Use a positive amount','Call check(5) and observe the returned value.','A reverted call does not keep its state changes.'),
L('view-functions','Read state without changing it','view allows reading contract state. Call doubled() to read twice the stored score.',sol('uint256 private score = 4;\nfunction doubled() external view returns (uint256) { return score * 2; }'),'8','Change the starting score before a fresh VM deployment.','pure cannot read state; use view when state is needed.')])
course('plsql','PL/SQL','sql','Examples use Oracle Database 19c or later with SQL*Plus-style script commands.','Use an Oracle practice database and SQL Developer Run Script or SQL*Plus. Run the whole block, including SET SERVEROUTPUT ON and the final slash. The result shown is DBMS_OUTPUT text.','PL/SQL adds variables, choices and loops to Oracle SQL. It is used to work with data inside an Oracle database.',[
L('first-message','Write a message','An anonymous block has BEGIN and END. DBMS_OUTPUT.PUT_LINE writes a line for the client to show.','SET SERVEROUTPUT ON\nBEGIN\n DBMS_OUTPUT.PUT_LINE(\'Hello, Asha!\');\nEND;\n/','Hello, Asha!','Change the name.','Enable server output or the client may hide the message.'),
L('variables','Name a number','DECLARE introduces local values. := assigns a value.',pl('pencils PLS_INTEGER := 3;', 'DBMS_OUTPUT.PUT_LINE(pencils + 2);'),'5','Start with 6 pencils.','Assignment uses :=, while = is a comparison.'),
L('strings','Join pieces of text','VARCHAR2 holds text. Two vertical bars join text.',pl("name VARCHAR2(20) := 'Ravi';", "DBMS_OUTPUT.PUT_LINE('Hi, ' || name || '!');"),'Hi, Ravi!','Use your own name.','Use single quotes for text literals.'),
L('choices','Choose an action','IF checks a rule. END IF ends its branches.',pl('score PLS_INTEGER := 8;', "IF score >= 5 THEN\n DBMS_OUTPUT.PUT_LINE('Pass');\nELSE\n DBMS_OUTPUT.PUT_LINE('Try again');\nEND IF;"),'Pass','Try score 3.','Close an IF with END IF, not only END.'),
L('case','Choose from labels','CASE matches a value with labels. ELSE is a fallback.',pl("light VARCHAR2(10) := 'green';", "CASE light\n WHEN 'red' THEN DBMS_OUTPUT.PUT_LINE('Stop');\n WHEN 'green' THEN DBMS_OUTPUT.PUT_LINE('Go');\n ELSE DBMS_OUTPUT.PUT_LINE('Wait');\nEND CASE;"),'Go','Try yellow.','Without an ELSE, an unmatched statement CASE can raise an error.'),
L('loops','Count with a FOR loop','A numeric FOR loop creates a counter and includes both ends.','SET SERVEROUTPUT ON\nBEGIN\n FOR n IN 1..3 LOOP\n  DBMS_OUTPUT.PUT_LINE(n);\n END LOOP;\nEND;\n/','1\n2\n3','Count through 4.','Do not assign a new value to the FOR loop counter.'),
L('while','Repeat while a rule is true','WHILE checks its rule before each repetition.',pl('n PLS_INTEGER := 1;', 'WHILE n <= 3 LOOP\n DBMS_OUTPUT.PUT_LINE(n);\n n := n + 1;\nEND LOOP;'),'1\n2\n3','Stop after 4.','Update the counter so the loop can stop.'),
L('records','Group named fields','A record groups related values into one local data item.',pl('TYPE book_type IS RECORD (title VARCHAR2(30), pages PLS_INTEGER);\nbook book_type;', "book.title := 'Moon Trip';\nbook.pages := 24;\nDBMS_OUTPUT.PUT_LINE(book.pages);"),'24','Print the title instead.','Set a field before assuming it has a useful value.'),
L('collections','Use a named lookup','An associative array stores values by key. This one uses text keys.',pl('TYPE scores_type IS TABLE OF PLS_INTEGER INDEX BY VARCHAR2(20);\nscores scores_type;', "scores('Asha') := 8;\nDBMS_OUTPUT.PUT_LINE(scores('Asha'));"),'8','Add a score for Ravi.','Use EXISTS before reading a key that may be absent.'),
L('functions','Return a result','A local function gives reusable steps a name and returns a typed value.',pl('FUNCTION twice(n PLS_INTEGER) RETURN PLS_INTEGER IS\nBEGIN\n RETURN n * 2;\nEND;', 'DBMS_OUTPUT.PUT_LINE(twice(4));'),'8','Call twice(7).','A function must return a value on its successful path.'),
L('exceptions','Handle a known error','EXCEPTION handles a failure in the block. ZERO_DIVIDE is the name for division by zero.',pl('answer NUMBER;', "answer := 1 / 0;\nEXCEPTION\n WHEN ZERO_DIVIDE THEN DBMS_OUTPUT.PUT_LINE('Cannot divide by zero');"),'Cannot divide by zero','Replace the divisor with 2 and print answer.','Handle a named expected error rather than silently hiding all errors.'),
L('null','Use a fallback for NULL','NULL means no value. NVL chooses a fallback when its first input is NULL.',pl('name VARCHAR2(20);', "DBMS_OUTPUT.PUT_LINE(NVL(name, 'Guest'));"),'Guest','Set name to Asha.','Test missing values with IS NULL, not = NULL.')])
course('tsql','T-SQL','sql','Examples use SQL Server 2017 or later. Each query is a separate batch.','Connect to a practice SQL Server database with SSMS or sqlcmd. Run one example at a time. Results below show cell values or PRINT text without grid headers.','T-SQL is the SQL language used by Microsoft SQL Server. It adds variables and control steps to table queries.',[
L('first-query','Ask for a message','SELECT asks for a result. AS gives its column a name.',"SELECT 'Hello, Asha!' AS message;",'Hello, Asha!','Change the name.','Text literals use single quotes.'),
L('variables','Name a local number','DECLARE makes a local variable. T-SQL variable names start with @.','DECLARE @pencils int = 3;\nSELECT @pencils + 2 AS total;','5','Start with 6 pencils.','The variable exists only in its batch or procedure scope.'),
L('text','Join text values','CONCAT joins values as text. It can also convert simple number inputs to text.',"SELECT CONCAT('Hi, ', 'Ravi', '!') AS message;",'Hi, Ravi!','Add a score to the message.','Do not assume + behaves the same way with NULL and mixed types.'),
L('case','Choose a result','CASE returns a value from the first matching branch.','DECLARE @score int = 8;\nSELECT CASE WHEN @score >= 5 THEN \'Pass\' ELSE \'Try again\' END AS message;','Pass','Try score 3.','CASE ends with END; it is an expression, not an IF block.'),
L('if','Choose which statement runs','IF controls which SQL statements run. BEGIN and END group statements.','DECLARE @score int = 8;\nIF @score >= 5\n BEGIN PRINT \'Pass\'; END\nELSE\n BEGIN PRINT \'Try again\'; END;','Pass','Try score 3.','Use BEGIN and END when a branch has several statements.'),
L('table-values','Make a small result table','VALUES can create rows for a query. An alias names the tiny table and its column.','SELECT n FROM (VALUES (3), (1), (2)) AS numbers(n) ORDER BY n;','1\n2\n3','Add (4).','Use ORDER BY when the row order matters.'),
L('filters','Keep matching rows','WHERE keeps rows that pass a condition.','SELECT n FROM (VALUES (4), (8), (9)) AS scores(n) WHERE n >= 7 ORDER BY n;','8\n9','Raise the limit to 9.','WHERE filters rows before they are grouped.'),
L('totals','Add values across rows','SUM adds a column over the selected rows.','SELECT SUM(n) AS total FROM (VALUES (2), (3), (4)) AS numbers(n);','9','Add another row with 5.','SUM ignores NULL inputs; it does not treat them as a known zero.'),
L('nulls','Choose a missing-value fallback','COALESCE returns the first input that is not NULL.','DECLARE @name varchar(20) = NULL;\nSELECT COALESCE(@name, \'Guest\') AS name;','Guest','Give @name the value Asha.','Use IS NULL for a null test, not = NULL.'),
L('safe-conversion','Read a number safely','TRY_CONVERT returns NULL when this text cannot be converted to int. COALESCE then supplies zero.',"SELECT COALESCE(TRY_CONVERT(int, 'cat'), 0) AS score;",'0','Try the text 12.','A failed conversion is not automatically a real score of zero; choose a suitable fallback for your app.'),
L('loops','Repeat with WHILE','WHILE repeats its block while a rule stays true.','DECLARE @n int = 1;\nWHILE @n <= 3\nBEGIN\n PRINT @n;\n SET @n = @n + 1;\nEND;','1\n2\n3','Count through 4.','Change the loop value so the loop eventually stops.'),
L('json','Read a JSON field','JSON_VALUE reads one simple value from JSON text using a path.',"SELECT JSON_VALUE('{\"title\":\"Moon Trip\",\"pages\":24}', '$.title') AS title;",'Moon Trip','Read $.pages.','Use valid JSON with double-quoted field names.')])
